41	// newAgentHelpCmd builds the `entire agent-help` command. It is visible in
42	// `entire help` (so agents on transports without context injection can still
43	// find it) and renders agent-facing usage live from rootCmd's command tree.
44	func newAgentHelpCmd(rootCmd *cobra.Command) *cobra.Command {
45		var asJSON bool
46		cmd := &cobra.Command{
47			Use:   "agent-help [command...]",
48			Short: "Machine-readable usage for coding agents (always matches the installed CLI)",
49			Long: `Prints agent-facing usage for the Entire CLI, generated live from the installed
50	command tree so it always matches this binary. With no arguments it prints a
51	high-level map of when to use entire and which subcommand; pass a command path
52	(e.g. "agent-help checkpoint") to see that command's exact, current flags.`,
53			RunE: func(c *cobra.Command, args []string) error {
54				// Resolve the origin remote once and derive both the repo line and the
55				// trails-enablement check from it (avoids two git subprocesses per run).
56				repoLine, trailsEnabled := agentHelpRepoContext(c.Context())
57				out, err := runAgentHelp(rootCmd, args, repoLine, asJSON, trailsEnabled)
58				if err != nil {
59					return err
60				}
61				fmt.Fprint(c.OutOrStdout(), out)
62				return nil
63			},
64		}
65		cmd.Flags().BoolVar(&asJSON, "json", false, "Emit structured JSON instead of text")
66		return cmd
67	}
