172	// agentHelpFindChild finds a direct child of parent by name or alias. It
173	// includes hidden commands so an annotated one like trail resolves; the caller
174	// (runAgentHelp) then enforces isAgentHelpAdvertised, so the drillable surface
175	// matches the advertised one.
176	func agentHelpFindChild(parent *cobra.Command, name string) *cobra.Command {
177		for _, sub := range parent.Commands() {
178			if sub.Name() == name {
179				return sub
180			}
181			for _, alias := range sub.Aliases {
182				if alias == name {
183					return sub
184				}
185			}
186		}
187		return nil
188	}
