248	// isAgentHelpAdvertised reports whether sub should be exposed to agents through
249	// agent-help. The listing AND the drill-down resolver share this predicate so
250	// the drillable surface always matches the advertised surface: visible commands
251	// plus hidden commands that opt in via agentHelpAnnotation, minus the help
252	// command, deprecated commands, and (when trails are disabled) trail-gated ones.
253	func isAgentHelpAdvertised(sub *cobra.Command, trailsEnabled bool) bool {
254		if sub.Name() == "help" || sub.Name() == "agent-help" || sub.Deprecated != "" {
255			return false
256		}
257		if sub.Hidden && sub.Annotations[agentHelpAnnotation] != agentHelpAnnotationEnabled {
258			return false
259		}
260		if !trailsEnabled && sub.Annotations[agentHelpRequiresTrailsAnnotation] == agentHelpAnnotationEnabled {
261			return false
262		}
263		return true
264	}
